CREATE TABLE `velix_production_artifacts` (`id` text PRIMARY KEY NOT NULL, `run_id` text NOT NULL REFERENCES `velix_production_runs`(`id`) ON DELETE CASCADE, `stage_id` text NOT NULL REFERENCES `velix_production_stages`(`id`) ON DELETE CASCADE, `kind` text NOT NULL, `relative_path` text, `content_hash` text NOT NULL, `mime` text, `metadata` text NOT NULL DEFAULT '{}', `created_at` text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')))
